def _distributed_is_initialized() -> bool:
    return dist.is_available() and dist.is_initialized()


def _distributed_rank() -> int:
    if _distributed_is_initialized():
        return int(dist.get_rank())
    return int(os.environ.get("RANK", "0"))


def _distributed_world_size() -> int:
    if _distributed_is_initialized():
        return int(dist.get_world_size())
    return int(os.environ.get("WORLD_SIZE", "1"))


def _distributed_is_rank0() -> bool:
    return _distributed_rank() == 0


def _distributed_should_write() -> bool:
    return _distributed_world_size() <= 1 or _distributed_is_rank0()


def _interactive_progress_enabled() -> bool:
    """Show carriage-return progress bars only on rank 0 of a real terminal.

    coda_runner merges stderr into ``tee`` for durable logs. In that piped
    mode tqdm's carriage returns are commonly rendered as a new line for every
    refresh, so structured logs are preferable to a corrupted progress bar.
    """

    isatty = getattr(sys.stderr, "isatty", None)
    return bool(
        _distributed_is_rank0()
        and callable(isatty)
        and isatty()
    )


def _distributed_barrier() -> None:
    if _distributed_is_initialized() and _distributed_world_size() > 1:
        if torch.cuda.is_available():
            try:
                dist.barrier(device_ids=[torch.cuda.current_device()])
                return
            except TypeError:
                pass
        dist.barrier()


def _raise_if_distributed_phase_failed(
    phase: str,
    local_error: BaseException | None,
) -> None:
    """Synchronize a phase result so one rank cannot strand the others."""
    if not _distributed_is_initialized() or _distributed_world_size() <= 1:
        if local_error is not None:
            raise RuntimeError(
                f"Distributed phase {phase!r} failed: "
                f"{type(local_error).__name__}: {local_error}"
            ) from local_error
        return

    local_status = {
        "rank": _distributed_rank(),
        "ok": local_error is None,
        "error": (
            None
            if local_error is None
            else f"{type(local_error).__name__}: {local_error}"
        ),
    }
    statuses: list[dict[str, Any] | None] = [None] * _distributed_world_size()
    dist.all_gather_object(statuses, local_status)
    failures = sorted(
        (
            status
            for status in statuses
            if status is not None and not bool(status.get("ok", False))
        ),
        key=lambda status: int(status.get("rank", -1)),
    )
    if not failures:
        return
    details = "; ".join(
        f"rank{int(status.get('rank', -1))}: {status.get('error', 'unknown error')}"
        for status in failures
    )
    message = f"Distributed phase {phase!r} failed consistently across ranks ({details})"
    if local_error is not None:
        raise RuntimeError(message) from local_error
    raise RuntimeError(message)


def _run_rank0_store_synchronized_phase(
    phase: str,
    operation: Callable[[], None],
    *,
    timeout: timedelta | None = None,
) -> None:
    """Run long rank-0-only work without holding an NCCL collective open.

    Object collectives inherit the process-group timeout, which is too short
    for a multi-fold artifact inference migration.  A quick broadcast gives
    every rank a fresh key, then nonzero ranks wait on the process store while
    rank 0 performs the work.  The final status is therefore propagated
    without keeping a CUDA collective pending for the duration of inference.
    """
    if timeout is None:
        timeout_seconds = float(
            os.environ.get("STOCKAGENT_DISTRIBUTED_PHASE_TIMEOUT_SECONDS", "86400")
        )
        if not math.isfinite(timeout_seconds) or timeout_seconds <= 0.0:
            raise ValueError(
                "STOCKAGENT_DISTRIBUTED_PHASE_TIMEOUT_SECONDS must be finite and > 0"
            )
        timeout = timedelta(seconds=timeout_seconds)

    if not _distributed_is_initialized():
        if _distributed_world_size() > 1:
            raise RuntimeError(
                f"Distributed phase {phase!r} requires an initialized process group"
            )
        operation()
        return
    if _distributed_world_size() <= 1:
        operation()
        return

    token: list[str | None] = [
        f"{time.time_ns()}-{os.getpid()}" if _distributed_is_rank0() else None
    ]
    dist.broadcast_object_list(token, src=0)
    if token[0] is None:
        raise RuntimeError(f"Distributed phase {phase!r} did not receive a store token")
    phase_key = f"stockagent/{phase}/{token[0]}"
    store = dist.distributed_c10d._get_default_store()
    rank = _distributed_rank()
    ack_key = f"{phase_key}/ack/{rank}"
    ack_keys = [
        f"{phase_key}/ack/{item_rank}"
        for item_rank in range(_distributed_world_size())
    ]

    local_error: BaseException | None = None
    status: dict[str, Any]
    if _distributed_is_rank0():
        try:
            operation()
            status = {"ok": True, "error": None}
        except BaseException as exc:
            local_error = exc
            status = {
                "ok": False,
                "error": f"{type(exc).__name__}: {exc}",
            }
        store.set(phase_key, json.dumps(status))
        store.set(ack_key, json.dumps({"ok": True, "error": None}))
        try:
            store.wait(ack_keys, timeout)
            acknowledgements = [
                json.loads(store.get(key).decode("utf-8"))
                for key in ack_keys
            ]
        except BaseException as exc:
            raise RuntimeError(
                f"Distributed phase {phase!r} did not receive every rank acknowledgement"
            ) from exc
        failed_acknowledgements = [
            (item_rank, acknowledgement.get("error"))
            for item_rank, acknowledgement in enumerate(acknowledgements)
            if not bool(acknowledgement.get("ok", False))
        ]
        if failed_acknowledgements:
            details = "; ".join(
                f"rank{item_rank}: {error}"
                for item_rank, error in failed_acknowledgements
            )
            raise RuntimeError(
                f"Distributed phase {phase!r} acknowledgement failed ({details})"
            )
    else:
        receive_error: BaseException | None = None
        try:
            store.wait([phase_key], timeout)
            raw_status = store.get(phase_key)
            status = json.loads(raw_status.decode("utf-8"))
        except BaseException as exc:
            receive_error = exc
            status = {
                "ok": False,
                "error": f"rank 0 status unavailable: {type(exc).__name__}: {exc}",
            }
        store.set(
            ack_key,
            json.dumps(
                {
                    "ok": receive_error is None,
                    "error": None if receive_error is None else status["error"],
                }
            ),
        )
        if receive_error is not None:
            raise RuntimeError(
                f"Distributed phase {phase!r} did not receive rank 0 status"
            ) from receive_error

    if not bool(status.get("ok", False)):
        message = f"Distributed phase {phase!r} failed on rank 0: {status.get('error')}"
        if local_error is not None:
            raise RuntimeError(message) from local_error
        raise RuntimeError(message)


@dataclass
class _Rank0StorePhase:
    """Store-backed rendezvous for rank-0 work that may exceed NCCL timeout."""

    phase: str
    timeout: timedelta
    enabled: bool
    rank: int = 0
    store: Any = None
    phase_key: str = ""
    ack_key: str = ""
    ack_keys: tuple[str, ...] = ()

    def finish(self, local_error: BaseException | None) -> None:
        if not self.enabled:
            if local_error is not None:
                raise RuntimeError(
                    f"Distributed phase {self.phase!r} failed: "
                    f"{type(local_error).__name__}: {local_error}"
                ) from local_error
            return

        status: dict[str, Any]
        if self.rank == 0:
            status = {
                "ok": local_error is None,
                "error": (
                    None
                    if local_error is None
                    else f"{type(local_error).__name__}: {local_error}"
                ),
            }
            self.store.set(self.phase_key, json.dumps(status))
            self.store.set(self.ack_key, json.dumps({"ok": True, "error": None}))
            try:
                self.store.wait(list(self.ack_keys), self.timeout)
                acknowledgements = [
                    json.loads(self.store.get(key).decode("utf-8"))
                    for key in self.ack_keys
                ]
            except BaseException as exc:
                raise RuntimeError(
                    f"Distributed phase {self.phase!r} did not receive every rank acknowledgement"
                ) from exc
            failed = [
                (item_rank, acknowledgement.get("error"))
                for item_rank, acknowledgement in enumerate(acknowledgements)
                if not bool(acknowledgement.get("ok", False))
            ]
            if failed:
                details = "; ".join(
                    f"rank{item_rank}: {error}" for item_rank, error in failed
                )
                raise RuntimeError(
                    f"Distributed phase {self.phase!r} acknowledgement failed ({details})"
                )
        else:
            receive_error: BaseException | None = None
            try:
                self.store.wait([self.phase_key], self.timeout)
                status = json.loads(self.store.get(self.phase_key).decode("utf-8"))
            except BaseException as exc:
                receive_error = exc
                status = {
                    "ok": False,
                    "error": f"rank 0 status unavailable: {type(exc).__name__}: {exc}",
                }
            self.store.set(
                self.ack_key,
                json.dumps(
                    {
                        "ok": receive_error is None,
                        "error": None if receive_error is None else status["error"],
                    }
                ),
            )
            if receive_error is not None:
                raise RuntimeError(
                    f"Distributed phase {self.phase!r} did not receive rank 0 status"
                ) from receive_error

        if not bool(status.get("ok", False)):
            message = (
                f"Distributed phase {self.phase!r} failed on rank 0: "
                f"{status.get('error')}"
            )
            if local_error is not None:
                raise RuntimeError(message) from local_error
            raise RuntimeError(message)


def _begin_rank0_store_synchronized_phase(
    phase: str,
    *,
    timeout: timedelta | None = None,
) -> _Rank0StorePhase:
    """Open a short NCCL rendezvous, then return a store-backed phase handle."""
    if timeout is None:
        timeout_seconds = float(
            os.environ.get("STOCKAGENT_DISTRIBUTED_PHASE_TIMEOUT_SECONDS", "86400")
        )
        if not math.isfinite(timeout_seconds) or timeout_seconds <= 0.0:
            raise ValueError(
                "STOCKAGENT_DISTRIBUTED_PHASE_TIMEOUT_SECONDS must be finite and > 0"
            )
        timeout = timedelta(seconds=timeout_seconds)

    if not _distributed_is_initialized():
        if _distributed_world_size() > 1:
            raise RuntimeError(
                f"Distributed phase {phase!r} requires an initialized process group"
            )
        return _Rank0StorePhase(phase=phase, timeout=timeout, enabled=False)
    if _distributed_world_size() <= 1:
        return _Rank0StorePhase(phase=phase, timeout=timeout, enabled=False)

    token: list[str | None] = [
        f"{time.time_ns()}-{os.getpid()}" if _distributed_is_rank0() else None
    ]
    dist.broadcast_object_list(token, src=0)
    if token[0] is None:
        raise RuntimeError(f"Distributed phase {phase!r} did not receive a store token")
    phase_key = f"stockagent/{phase}/{token[0]}"
    rank = _distributed_rank()
    return _Rank0StorePhase(
        phase=phase,
        timeout=timeout,
        enabled=True,
        rank=rank,
        store=dist.distributed_c10d._get_default_store(),
        phase_key=phase_key,
        ack_key=f"{phase_key}/ack/{rank}",
        ack_keys=tuple(
            f"{phase_key}/ack/{item_rank}"
            for item_rank in range(_distributed_world_size())
        ),
    )


@contextmanager
def _preserve_process_rng_state(device: torch.device | None = None):
    """Keep non-training preflight work from advancing any stochastic stream."""
    python_state = random.getstate()
    numpy_state = np.random.get_state()
    rng_devices: list[int] = []
    if device is not None and device.type == "cuda":
        rng_devices = [
            int(device.index)
            if device.index is not None
            else int(torch.cuda.current_device())
        ]
    try:
        with torch.random.fork_rng(devices=rng_devices, enabled=True):
            yield
    finally:
        random.setstate(python_state)
        np.random.set_state(numpy_state)


def _all_gather_autograd(x: torch.Tensor) -> torch.Tensor:
    if _distributed_world_size() <= 1:
        return x
    if dist_fc is not None and hasattr(dist_fc, "all_gather_tensor"):
        gathered = dist_fc.all_gather_tensor(x, 0, group=dist.group.WORLD)
        # Do not pass AsyncCollectiveTensor/unbacked symbolic storage into a
        # separately compiled loss graph. PyTorch 2.12 can otherwise attempt a
        # second guard specialization in can_use_32bit_indexing and fail while
        # constructing its ShapeEnv guard. wait_tensor preserves autograd while
        # presenting the canonical loss with an ordinary realized tensor.
        if hasattr(dist_fc, "wait_tensor"):
            gathered = dist_fc.wait_tensor(gathered)
        return gathered
    parts = dist_nn_f.all_gather(x)
    return torch.cat(tuple(parts), dim=0)


def _all_gather_no_grad(x: torch.Tensor) -> torch.Tensor:
    world_size = _distributed_world_size()
    if world_size <= 1:
        return x
    if hasattr(dist, "all_gather_into_tensor") and x.dim() > 0:
        # DDP training uses equal fixed-shape shards.  Gather directly into the
        # final dim-0-concatenated buffer instead of allocating one buffer per
        # rank and launching a second device-side cat for every execution
        # tensor.  Values and global rank ordering are identical.
        gathered = torch.empty(
            (world_size * int(x.size(0)), *tuple(x.shape[1:])),
            device=x.device,
            dtype=x.dtype,
        )
        dist.all_gather_into_tensor(gathered, x)
        return gathered
    parts = [torch.empty_like(x) for _ in range(world_size)]
    dist.all_gather(parts, x)
    return torch.cat(parts, dim=0)


def _time_to_symbol_all_to_all_autograd(x: torch.Tensor) -> torch.Tensor:
    """Transpose equal DDP time shards into equal contiguous symbol shards.

    Input rank ``r`` owns ``[b, ..., S]`` for one contiguous time range.  The
    returned rank ``r`` owns ``[G*b, ..., S/G]`` for one contiguous symbol
    range and every time row.  Backward is provided by PyTorch's functional
    collective; this executor intentionally has no custom autograd Function.
    """

    world_size = _distributed_world_size()
    if world_size <= 1:
        return x
    if x.dim() < 2:
        raise ValueError("time-to-symbol All-to-All requires shape [time,...,symbol]")
    symbols = int(x.size(-1))
    local_rows = int(x.size(0))
    if symbols % world_size != 0:
        raise ValueError(
            "symbol count must be divisible by world_size for equal symbol shards; "
            f"symbols={symbols}, world_size={world_size}"
        )
    if dist_fc is None or not hasattr(dist_fc, "all_to_all_single_autograd"):
        raise RuntimeError(
            "this PyTorch build lacks functional autograd All-to-All required "
            "by distributed_symbol_sharded_ledger"
        )
    send = torch.cat(tuple(x.chunk(world_size, dim=-1)), dim=0).contiguous()
    split_rows = [local_rows] * world_size
    routed = dist_fc.all_to_all_single_autograd(
        send,
        split_rows,
        split_rows,
        dist.group.WORLD,
    )
    if hasattr(dist_fc, "wait_tensor"):
        routed = dist_fc.wait_tensor(routed)
    return routed


def _time_to_symbol_all_to_all_no_grad(x: torch.Tensor) -> torch.Tensor:
    """Non-autograd twin of :func:`_time_to_symbol_all_to_all_autograd`."""

    world_size = _distributed_world_size()
    if world_size <= 1:
        return x
    if x.dim() < 2:
        raise ValueError("time-to-symbol All-to-All requires shape [time,...,symbol]")
    symbols = int(x.size(-1))
    local_rows = int(x.size(0))
    if symbols % world_size != 0:
        raise ValueError(
            "symbol count must be divisible by world_size for equal symbol shards; "
            f"symbols={symbols}, world_size={world_size}"
        )
    send = torch.cat(tuple(x.chunk(world_size, dim=-1)), dim=0).contiguous()
    output = torch.empty_like(send)
    split_rows = [local_rows] * world_size
    dist.all_to_all_single(
        output,
        send,
        output_split_sizes=split_rows,
        input_split_sizes=split_rows,
    )
    return output


def _time_to_symbol_all_to_all_no_grad_many(
    tensors: Sequence[torch.Tensor],
) -> tuple[torch.Tensor, ...]:
    """Pack same-dtype execution tensors into one time-to-symbol collective."""

    values = tuple(tensors)
    if not values:
        return ()
    reference = values[0]
    if reference.dim() < 2:
        raise ValueError("packed time-to-symbol inputs require a symbol axis")
    rows = int(reference.size(0))
    symbols = int(reference.size(-1))
    widths: list[int] = []
    shapes: list[tuple[int, ...]] = []
    flattened: list[torch.Tensor] = []
    for value in values:
        if (
            int(value.size(0)) != rows
            or int(value.size(-1)) != symbols
            or value.dtype != reference.dtype
            or value.device != reference.device
        ):
            raise ValueError(
                "packed time-to-symbol tensors must share time, symbol, dtype, and device"
            )
        middle_shape = tuple(int(item) for item in value.shape[1:-1])
        width = math.prod(middle_shape) if middle_shape else 1
        widths.append(width)
        shapes.append(middle_shape)
        flattened.append(value.reshape(rows, width, symbols))
    packed = torch.cat(flattened, dim=1).contiguous()
    routed = _time_to_symbol_all_to_all_no_grad(packed)
    local_symbols = int(routed.size(-1))
    outputs: list[torch.Tensor] = []
    offset = 0
    for width, middle_shape in zip(widths, shapes, strict=True):
        outputs.append(
            routed[:, offset : offset + width].reshape(
                int(routed.size(0)),
                *middle_shape,
                local_symbols,
            )
        )
        offset += width
    return tuple(outputs)


def _symbol_sharded_pack_metadata_enabled() -> bool:
    """Return the process-local metadata-coalescing ablation switch."""

    return os.environ.get("STOCKAGENT_SYMBOL_SHARDED_PACK_METADATA", "1") != "0"


def _route_ddp_batch_to_symbol_shards(
    local_weights: torch.Tensor,
    batch: Mapping[str, torch.Tensor],
    *,
    include_volume_notional: bool,
    include_short_capacity_notional: bool,
) -> dict[str, torch.Tensor | None]:
    """Route one fixed-shape DDP time batch to the recurrent ledger layout.

    Tensor packing bounds the transpose to one collective per metadata dtype,
    plus the autograd action collective. Account-wide time-only fields remain
    replicated through packed All-Gather operations.
    """

    world_size = _distributed_world_size()
    rank = _distributed_rank()
    if world_size <= 1:
        raise RuntimeError("symbol-sharded routing requires world_size greater than one")
    global_symbols = int(local_weights.size(-1))
    if global_symbols % world_size != 0:
        raise RuntimeError(
            "symbol-sharded routing requires an equal symbol partition; "
            f"symbols={global_symbols}, world_size={world_size}"
        )

    routed: dict[str, torch.Tensor | None] = {
        "weights": _time_to_symbol_all_to_all_autograd(local_weights.contiguous())
    }
    symbol_keys = [
        "future_log_returns",
        "overnight_log_returns",
        "tradable_mask",
        "can_buy_mask",
        "can_sell_mask",
        "can_short_open_mask",
        "force_short_cover_mask",
        "force_exit_mask",
        "day_trade_eligible_mask",
        "day_trade_can_buy_open_mask",
        "day_trade_can_sell_open_mask",
        "can_short_open_open_mask",
        "unresolved_corporate_action_mask",
        "cash_dividend_yield",
        "cash_dividend_payment_delay_sessions",
    ]
    if include_volume_notional:
        symbol_keys.append("volume_notional")
    if include_short_capacity_notional:
        symbol_keys.append("short_capacity_notional")
    if "short_margin_rate" in batch:
        symbol_keys.append("short_margin_rate")

    present = [(key, batch[key].contiguous()) for key in symbol_keys if key in batch]
    dtype_groups: dict[torch.dtype, list[tuple[str, torch.Tensor]]] = {}
    for key, value in present:
        dtype_groups.setdefault(value.dtype, []).append((key, value))
    for dtype, items in dtype_groups.items():
        route_values = tuple(value for _, value in items)
        restore_bool = dtype == torch.bool
        if restore_bool:
            route_values = tuple(value.to(dtype=torch.uint8) for value in route_values)
        outputs = (
            _time_to_symbol_all_to_all_no_grad_many(route_values)
            if _symbol_sharded_pack_metadata_enabled()
            else tuple(
                _time_to_symbol_all_to_all_no_grad_many((value,))[0]
                for value in route_values
            )
        )
        for (key, _), output in zip(items, outputs, strict=True):
            routed[key] = output.to(dtype=torch.bool) if restore_bool else output

    time_keys = [
        "sample_mask",
        "session_advance_mask",
        "session_month_ids",
        "commission_rebate_payment_eligible_mask",
        "benchmark",
    ]
    time_groups: dict[torch.dtype, list[tuple[str, torch.Tensor]]] = {}
    for key in time_keys:
        value = batch[key].contiguous()
        time_groups.setdefault(value.dtype, []).append((key, value))
    for dtype, items in time_groups.items():
        restore_bool = dtype == torch.bool
        columns = tuple(
            (value.to(dtype=torch.uint8) if restore_bool else value).reshape(
                int(value.size(0)), -1
            )
            for _, value in items
        )
        widths = [int(value.size(1)) for value in columns]
        if _symbol_sharded_pack_metadata_enabled():
            gathered = _all_gather_no_grad(torch.cat(columns, dim=1).contiguous())
            offset = 0
            for (key, original), width in zip(items, widths, strict=True):
                value = gathered[:, offset : offset + width].reshape(
                    _distributed_world_size() * int(original.size(0)),
                    *tuple(int(item) for item in original.shape[1:]),
                )
                routed[key] = value.to(dtype=torch.bool) if restore_bool else value
                offset += width
        else:
            for (key, original), column in zip(items, columns, strict=True):
                value = _all_gather_no_grad(column.contiguous()).reshape(
                    _distributed_world_size() * int(original.size(0)),
                    *tuple(int(item) for item in original.shape[1:]),
                )
                routed[key] = value.to(dtype=torch.bool) if restore_bool else value

    local_symbols = global_symbols // world_size
    symbol_start = rank * local_symbols
    symbol_stop = symbol_start + local_symbols
    source_symbol_indices = batch.get("symbol_indices")
    if source_symbol_indices is None:
        routed["symbol_indices"] = torch.arange(
            symbol_start,
            symbol_stop,
            device=local_weights.device,
            dtype=torch.long,
        )
    else:
        if int(source_symbol_indices.numel()) != global_symbols:
            raise RuntimeError(
                "DDP symbol index contract differs from model output: "
                f"indices={int(source_symbol_indices.numel())}, symbols={global_symbols}"
            )
        routed["symbol_indices"] = source_symbol_indices[
            symbol_start:symbol_stop
        ].to(device=local_weights.device, dtype=torch.long).contiguous()
    for optional_key in (
        "can_short_open_open_mask",
        "day_trade_eligible_mask",
        "day_trade_can_buy_open_mask",
        "day_trade_can_sell_open_mask",
        "unresolved_corporate_action_mask",
        "cash_dividend_yield",
        "cash_dividend_payment_delay_sessions",
        "volume_notional",
        "short_capacity_notional",
        "short_margin_rate",
    ):
        routed.setdefault(optional_key, None)
    return routed


def _route_ddp_batch_replicated(
    local_weights: torch.Tensor,
    batch: Mapping[str, torch.Tensor],
    *,
    include_volume_notional: bool,
    include_short_capacity_notional: bool,
    global_metadata: Mapping[str, torch.Tensor] | None = None,
) -> dict[str, torch.Tensor | None]:
    """Gather actions while keeping the full-symbol ledger replicated.

    ``global_metadata`` is an exact communication-elision path.  DDP ranks
    hold identical immutable execution panels, so only model-produced actions
    need an autograd collective.  Passing the locally sliced global rows avoids
    retransmitting deterministic returns, masks, capacities, and calendars.
    ``None`` preserves the historical all-gather oracle.
    """

    routed: dict[str, torch.Tensor | None] = {
        "weights": _all_gather_autograd(local_weights.contiguous()),
    }
    source = batch if global_metadata is None else global_metadata
    if global_metadata is not None:
        expected_rows = int(local_weights.size(0)) * _distributed_world_size()
        sample_mask = source.get("sample_mask")
        if sample_mask is None or int(sample_mask.size(0)) != expected_rows:
            raise RuntimeError(
                "replicated-ledger local metadata must contain the complete "
                f"global time batch; expected rows={expected_rows}"
            )
    symbol_keys = (
        "future_log_returns",
        "overnight_log_returns",
        "tradable_mask",
        "can_buy_mask",
        "can_sell_mask",
        "can_short_open_mask",
        "can_short_open_open_mask",
        "force_short_cover_mask",
        "force_exit_mask",
        "day_trade_eligible_mask",
        "day_trade_can_buy_open_mask",
        "day_trade_can_sell_open_mask",
        "unresolved_corporate_action_mask",
        "cash_dividend_yield",
        "cash_dividend_payment_delay_sessions",
        "short_margin_rate",
    )
    for key in symbol_keys:
        value = source.get(key)
        routed[key] = (
            None
            if value is None
            else value
            if global_metadata is not None
            else _all_gather_no_grad(value.contiguous())
        )
    for key in (
        "sample_mask",
        "session_advance_mask",
        "session_month_ids",
        "commission_rebate_payment_eligible_mask",
        "benchmark",
    ):
        value = source[key]
        routed[key] = (
            value
            if global_metadata is not None
            else _all_gather_no_grad(value.contiguous())
        )
    routed["volume_notional"] = (
        source["volume_notional"]
        if global_metadata is not None
        and include_volume_notional
        and "volume_notional" in source
        else _all_gather_no_grad(source["volume_notional"].contiguous())
        if include_volume_notional and "volume_notional" in source
        else None
    )
    routed["short_capacity_notional"] = (
        source["short_capacity_notional"]
        if global_metadata is not None
        and include_short_capacity_notional
        and "short_capacity_notional" in source
        else _all_gather_no_grad(source["short_capacity_notional"].contiguous())
        if include_short_capacity_notional and "short_capacity_notional" in source
        else None
    )
    routed["symbol_indices"] = source.get("symbol_indices")
    return routed


@contextmanager
def _temporary_env(name: str, value: str):
    previous = os.environ.get(name)
    os.environ[name] = value
    try:
        yield
    finally:
        if previous is None:
            os.environ.pop(name, None)
        else:
            os.environ[name] = previous


@dataclass(slots=True)
class FoldResult:
    fold_id: int
    train_years: list[int]
    val_years: list[int]
    test_years: list[int]
    best_val_loss: float
    val_ic: dict[str, float]
    val_metrics: dict[str, float]
    test_ic: dict[str, float]
    test_metrics: dict[str, float]
    test_integer_metrics: dict[str, float] | None = None
    test_continuous_surrogate_metrics: dict[str, float] | None = None


@dataclass(slots=True)
class FoldRuntimeContext:
    fold: WalkForwardFold
    fold_dir: Path
    val_ds: CrossSectionalDataset
    test_ds: CrossSectionalDataset
    deployment_test_rows: int
    checkpoint_best_path: Path
    best_val_loss: float = float("inf")


@dataclass(frozen=True, slots=True)
class _ExecutionRuntime:
    mode: str
    buy_fee_rates: torch.Tensor | None
    sell_fee_rates: torch.Tensor | None
    lot_sizes: np.ndarray | None
    settlement_lag_sessions: int
    crypto_stateful_proximal_allocator: bool = False
    crypto_proximal_cost_multiplier: float = 1.0
    normal_sell_fee_rates: torch.Tensor | None = None
    day_trade_unlimited_margin_conversion: bool = False
    day_trade_margin_financing_ratio: float = 0.60
    day_trade_margin_financing_annual_rate: float = 0.16
    day_trade_margin_short_handling_fee_rate: float = 0.001
    day_trade_margin_short_annual_borrow_rate: float = 0.20
    commission_rebate_rates: torch.Tensor | None = None
    commission_rebate_timing: str = "daily_close"
    minimum_commission: float = 0.0
    commission_rounding: str = "none"
    tax_rounding: str = "none"
    # Preserve the decimal schedule in float64 for the exact CPU oracle.  The
    # differentiable executor separately receives device tensors and casts to
    # its compute dtype.
    integer_buy_fee_rates: np.ndarray | None = None
    integer_sell_fee_rates: np.ndarray | None = None
    integer_commission_rebate_rates: np.ndarray | None = None
    short_lot_sizes: np.ndarray | None = None
    short_initial_margin_rate: float = 0.90
    short_handling_fee_rate: float = 0.0
    short_maintenance_ratio: float = 1.30
    short_capacity_limit_enabled: bool = True
    corporate_action_mode: str = "avoid"
    claim_queue_sessions: int = 2
    futures_market: TaiwanIndexFuturesDaySession | None = None
    futures_cost_schedule: FuturesCostSchedule | None = None
    futures_initial_capital: float = 100_000_000.0
    futures_max_abs_exposure: float = 1.0
    options_chain_market: TaiwanIndexOptionChainDaySession | None = None
    derivatives_day_candidates: TaiwanIndexDerivativeDayCandidates | None = None
    option_day_cost_schedule: OptionDayCostSchedule | None = None
    derivatives_maximum_capital_fraction: float = 0.98


def _is_stateful_security_carry(
    execution_mode: str,
    runtime: _ExecutionRuntime | None,
) -> bool:
    mode = normalize_execution_mode(execution_mode)
    return bool(
        mode in TW_CARRYING_EXECUTION_MODES
        or (
            mode == "tw_day_trade"
            and runtime is not None
            and runtime.day_trade_unlimited_margin_conversion
        )
    )


def _tw_settlement_compile_backend(
    execution_runtime: _ExecutionRuntime,
    *,
    day_trade_minute_compile: bool,
) -> str:
    """Return the bounded executor whose compile counters are authoritative.

    Stateful day-trade carry is implemented by the same dual-session ledger as
    ``tw_cash``/``tw_overnight``. Keeping this selection in one place prevents
    strict preflight from checking counters for a different executor than the
    one that actually ran.
    """

    if day_trade_minute_compile:
        return "day_trade_minute"
    if _is_stateful_security_carry(
        execution_runtime.mode,
        execution_runtime,
    ):
        return "dual_session"
    if execution_runtime.mode == "tw_index_futures_day":
        return "index_futures"
    return "continuous"


def _build_execution_runtime(
    panel: PanelData,
    config: ExperimentConfig,
    device: torch.device,
) -> _ExecutionRuntime:
    """Resolve one immutable execution schedule for the panel symbol order."""

    mode = normalize_execution_mode(config.trading.execution_mode)
    lag = int(config.trading.tw_settlement_lag_sessions)
    if mode in CONTINUOUS_WEIGHT_EXECUTION_MODES:
        return _ExecutionRuntime(
            mode=mode,
            buy_fee_rates=None,
            sell_fee_rates=None,
            commission_rebate_rates=None,
            commission_rebate_timing=str(
                config.trading.tw_commission_rebate_timing
            ),
            lot_sizes=None,
            settlement_lag_sessions=lag,
            crypto_stateful_proximal_allocator=(
                bool(config.trading.crypto_stateful_proximal_allocator)
                if mode == "crypto_perpetual"
                else False
            ),
            crypto_proximal_cost_multiplier=float(
                config.trading.crypto_proximal_cost_multiplier
            ),
        )
    if mode in {"tw_index_futures_day", "tw_index_derivatives_day"}:
        market = getattr(panel, "index_futures_day_session", None)
        if market is None:
            raise ValueError(
                f"{mode} requires aligned TAIFEX data attached by train.py"
            )
        exchange_fees = tuple(
            float(value)
            for value in config.trading.tw_index_futures_exchange_and_clearing_fee_per_side_twd
        )
        total_fees = tuple(
            float(value)
            for value in config.trading.tw_index_futures_total_fee_per_side_twd
        )
        broker_fees = tuple(
            total - exchange
            for total, exchange in zip(total_fees, exchange_fees, strict=True)
        )
        schedule = FuturesCostSchedule(
            tax_rate=float(
                config.trading.tw_index_futures_sell_transaction_tax_rate
            ),
            exchange_and_clearing_fee_per_side_twd=exchange_fees,
            broker_fee_per_side_twd=broker_fees,
            slippage_points_per_side=tuple(
                float(value)
                for value in config.trading.tw_index_futures_slippage_points_per_side
            ),
            basket_fee_penalty=float(
                config.trading.tw_index_futures_basket_fee_penalty
            ),
        )
        option_chain = getattr(panel, "index_options_chain_day_session", None)
        derivative_candidates = getattr(panel, "index_derivatives_day_candidates", None)
        if mode == "tw_index_derivatives_day" and (
            option_chain is None or derivative_candidates is None
        ):
            raise ValueError(
                "tw_index_derivatives_day requires the TXO chain and causal candidates"
            )
        option_schedule = (
            OptionDayCostSchedule(
                fixed_fee_per_contract_per_side_twd=float(
                    config.trading.tw_index_derivatives_day_option_fixed_fee_per_contract_per_side_twd
                ),
                transaction_tax_rate=float(
                    config.trading.tw_index_derivatives_day_option_transaction_tax_rate
                ),
                slippage_points_per_side=float(
                    config.trading.tw_index_derivatives_day_option_slippage_points_per_side
                ),
            )
            if mode == "tw_index_derivatives_day"
            else None
        )
        return _ExecutionRuntime(
            mode=mode,
            buy_fee_rates=None,
            sell_fee_rates=None,
            lot_sizes=None,
            settlement_lag_sessions=0,
            futures_market=market,
            futures_cost_schedule=schedule,
            futures_initial_capital=float(
                config.trading.tw_index_futures_initial_capital
            ),
            futures_max_abs_exposure=float(
                config.trading.tw_index_futures_max_abs_exposure
            ),
            options_chain_market=option_chain,
            derivatives_day_candidates=derivative_candidates,
            option_day_cost_schedule=option_schedule,
            derivatives_maximum_capital_fraction=float(
                config.trading.tw_index_derivatives_day_maximum_capital_fraction
            ),
        )
    stateful_security_carry = bool(
        mode in TW_CARRYING_EXECUTION_MODES
        or (
            mode == "tw_day_trade"
            and config.trading.tw_day_trade_unlimited_margin_conversion
        )
    )
    if stateful_security_carry and not bool(config.trading.long_only):
        if (
            panel.can_short_open_mask is None
            or getattr(panel, "can_short_open_open_mask", None) is None
        ):
            raise ValueError(
                f"long/short {mode} requires separate point-in-time open- and "
                "close-session margin-short eligibility; sellability alone is "
                "insufficient"
            )
        if (
            bool(config.trading.tw_short_capacity_limit_enabled)
            and panel.short_capacity_shares is None
        ):
            raise ValueError(
                f"long/short {mode} with capacity limiting enabled requires "
                "point-in-time demonstrated short capacity"
            )
    corporate_action_mode = str(config.trading.tw_corporate_action_mode)
    if stateful_security_carry:
        if corporate_action_mode == "avoid":
            execution_action_mask = getattr(
                panel, "corporate_action_avoidance_mask", None
            )
            has_exact_events = (
                panel.cash_dividend_yield is not None
                and bool((np.asarray(panel.cash_dividend_yield) > 0.0).any())
            )
            if execution_action_mask is None and not has_exact_events:
                # Synthetic and legacy panels with no exact event to restore
                # have identical all-action and unresolved masks.
                execution_action_mask = panel.unresolved_corporate_action_mask
        else:
            execution_action_mask = panel.unresolved_corporate_action_mask
        if execution_action_mask is None:
            raise ValueError(
                f"{corporate_action_mode} {mode} requires a source-derived, "
                "receipt-verified official corporate-action execution mask"
            )
    claim_queue_sessions = (
        int(config.trading.tw_corporate_action_claim_queue_sessions)
        if corporate_action_mode == "exact"
        else lag
    )
    if stateful_security_carry and corporate_action_mode == "exact":
        if (
            panel.cash_dividend_yield is None
            or panel.cash_dividend_payment_delay_sessions is None
        ):
            raise ValueError(
                f"exact {mode} requires a complete receipt-verified MOPS "
                "cash-dividend entitlement archive"
            )
        event_delays = np.asarray(
            panel.cash_dividend_payment_delay_sessions, dtype=np.int64
        )
        if event_delays.size and int(event_delays.max(initial=0)) > claim_queue_sessions:
            raise ValueError(
                "tw_corporate_action_claim_queue_sessions is shorter than an "
                "announced cash-dividend payment delay"
            )
    if mode == "tw_day_trade":
        if panel.open_prices is None or panel.intraday_returns is None:
            raise ValueError(
                "tw_day_trade requires point-in-time open prices and intraday returns"
            )
        if panel.day_trade_eligible_mask is None:
            raise ValueError(
                "tw_day_trade requires a point-in-time day_trade_eligible_mask; "
                "today's eligible list cannot be projected backward"
            )
        if (
            panel.day_trade_can_buy_open_mask is None
            or panel.day_trade_can_sell_open_mask is None
        ):
            raise ValueError(
                "tw_day_trade requires point-in-time open-session buy/sell masks; "
                "close-session masks must not be reused for the open"
            )
        if (
            not bool(config.trading.long_only)
            and panel.day_trade_can_short_open_mask is None
        ):
            raise ValueError(
                "long/short tw_day_trade requires a point-in-time "
                "day_trade_can_short_open_mask"
            )
    schedule = TaiwanFeeSchedule(
        commission_rate=config.trading.tw_commission_rate,
        commission_discount=config.trading.tw_commission_discount,
        commission_rebate_timing=config.trading.tw_commission_rebate_timing,
        stock_sell_tax=config.trading.tw_stock_sell_tax,
        etf_sell_tax=config.trading.tw_etf_sell_tax,
        day_trade_stock_sell_tax=config.trading.tw_day_trade_stock_sell_tax,
        day_trade_etf_sell_tax=config.trading.tw_day_trade_etf_sell_tax,
        minimum_commission=config.trading.tw_minimum_commission,
        commission_rounding=config.trading.tw_commission_rounding,
        tax_rounding=config.trading.tw_tax_rounding,
        settlement_lag_sessions=lag,
        cash_lot_size=config.trading.tw_cash_lot_size,
        day_trade_default_lot_size=config.trading.tw_day_trade_lot_size,
    )
    buy_rates, sell_rates = gross_fee_rate_vectors(
        panel.symbols,
        mode,
        fee_schedule=schedule,
    )
    _, normal_sell_rates = gross_fee_rate_vectors(
        panel.symbols,
        "tw_cash",
        fee_schedule=schedule,
    )
    rebate_rates = commission_rebate_rate_vector(
        panel.symbols,
        mode,
        fee_schedule=schedule,
    )
    lots = lot_size_vector(panel.symbols, mode, fee_schedule=schedule)
    short_schedule = TaiwanMarginShortSchedule(
        initial_margin_rate=config.trading.tw_short_initial_margin_rate,
        maintenance_ratio=config.trading.tw_short_maintenance_ratio,
        lot_size=config.trading.tw_short_lot_size,
        handling_fee_rate=config.trading.tw_short_handling_fee_rate,
    )
    return _ExecutionRuntime(
        mode=mode,
        buy_fee_rates=torch.as_tensor(
            buy_rates,
            device=device,
            dtype=torch.float32,
        ),
        sell_fee_rates=torch.as_tensor(
            sell_rates,
            device=device,
            dtype=torch.float32,
        ),
        normal_sell_fee_rates=torch.as_tensor(
            normal_sell_rates,
            device=device,
            dtype=torch.float32,
        ),
        day_trade_unlimited_margin_conversion=bool(
            config.trading.tw_day_trade_unlimited_margin_conversion
        ),
        day_trade_margin_financing_ratio=float(
            config.trading.tw_day_trade_margin_financing_ratio
        ),
        day_trade_margin_financing_annual_rate=float(
            config.trading.tw_day_trade_margin_financing_annual_rate
        ),
        day_trade_margin_short_handling_fee_rate=float(
            config.trading.tw_day_trade_margin_short_handling_fee_rate
        ),
        day_trade_margin_short_annual_borrow_rate=float(
            config.trading.tw_day_trade_margin_short_annual_borrow_rate
        ),
        commission_rebate_rates=torch.as_tensor(
            rebate_rates,
            device=device,
            dtype=torch.float32,
        ),
        commission_rebate_timing=schedule.commission_rebate_timing,
        lot_sizes=lots,
        settlement_lag_sessions=lag,
        minimum_commission=schedule.minimum_commission,
        commission_rounding=schedule.commission_rounding,
        tax_rounding=schedule.tax_rounding,
        integer_buy_fee_rates=buy_rates.copy(),
        integer_sell_fee_rates=sell_rates.copy(),
        integer_commission_rebate_rates=rebate_rates.copy(),
        short_lot_sizes=np.full(
            len(panel.symbols), short_schedule.lot_size, dtype=np.int64
        ),
        short_initial_margin_rate=short_schedule.initial_margin_rate,
        short_handling_fee_rate=short_schedule.handling_fee_rate,
        short_maintenance_ratio=short_schedule.maintenance_ratio,
        short_capacity_limit_enabled=bool(
            config.trading.tw_short_capacity_limit_enabled
        ),
        corporate_action_mode=corporate_action_mode,
        claim_queue_sessions=claim_queue_sessions,
    )


def _integer_execution_runtime_kwargs(
    runtime: _ExecutionRuntime,
    *,
    open_prices: np.ndarray | None,
    day_trade_eligible_mask: np.ndarray | None,
    day_trade_can_buy_open_mask: np.ndarray | None,
    day_trade_can_sell_open_mask: np.ndarray | None,
    unresolved_corporate_action_mask: np.ndarray | None,
    state_advance_mask: np.ndarray | None,
    cash_dividend_yield: np.ndarray | None = None,
    cash_dividend_payment_delay_sessions: np.ndarray | None = None,
    can_short_open_open_mask: np.ndarray | None = None,
    short_capacity_shares: np.ndarray | None = None,
    short_margin_rate: np.ndarray | None = None,
    symbol_indices: np.ndarray | None = None,
) -> dict[str, Any]:
    """Bridge the differentiable runtime schedule into the exact CPU oracle."""

    kwargs: dict[str, Any] = {"execution_mode": runtime.mode}
    if runtime.mode in CONTINUOUS_WEIGHT_EXECUTION_MODES:
        return kwargs
    if runtime.mode in {"tw_index_futures_day", "tw_index_derivatives_day"}:
        if runtime.futures_market is None or runtime.futures_cost_schedule is None:
            raise RuntimeError("futures integer audit runtime is incomplete")
        kwargs.update(
            futures_market=runtime.futures_market,
            futures_cost_schedule=runtime.futures_cost_schedule,
            futures_max_abs_exposure=runtime.futures_max_abs_exposure,
        )
        if runtime.mode == "tw_index_derivatives_day":
            if (
                runtime.options_chain_market is None
                or runtime.derivatives_day_candidates is None
                or runtime.option_day_cost_schedule is None
            ):
                raise RuntimeError("derivatives integer audit runtime is incomplete")
            kwargs.update(
                options_chain_market=runtime.options_chain_market,
                derivatives_day_candidates=runtime.derivatives_day_candidates,
                option_day_cost_schedule=runtime.option_day_cost_schedule,
                derivatives_maximum_capital_fraction=(
                    runtime.derivatives_maximum_capital_fraction
                ),
            )
        return kwargs
    if (
        runtime.buy_fee_rates is None
        or runtime.sell_fee_rates is None
        or runtime.lot_sizes is None
        or runtime.integer_buy_fee_rates is None
        or runtime.integer_sell_fee_rates is None
        or runtime.integer_commission_rebate_rates is None
    ):
        raise RuntimeError(f"{runtime.mode} integer audit schedule is incomplete")
    kwargs.update(
        buy_fee_rates=np.asarray(runtime.integer_buy_fee_rates, dtype=np.float64),
        sell_fee_rates=np.asarray(runtime.integer_sell_fee_rates, dtype=np.float64),
        commission_rebate_rates=np.asarray(
            runtime.integer_commission_rebate_rates,
            dtype=np.float64,
        ),
        commission_rebate_timing=runtime.commission_rebate_timing,
        lot_sizes=np.asarray(runtime.lot_sizes),
        open_prices=open_prices,
        day_trade_eligible_mask=day_trade_eligible_mask,
        day_trade_can_buy_open_mask=day_trade_can_buy_open_mask,
        day_trade_can_sell_open_mask=day_trade_can_sell_open_mask,
        unresolved_corporate_action_mask=unresolved_corporate_action_mask,
        cash_dividend_yield=cash_dividend_yield,
        cash_dividend_payment_delay_sessions=(
            cash_dividend_payment_delay_sessions
        ),
        claim_queue_sessions=runtime.claim_queue_sessions,
        state_advance_mask=state_advance_mask,
        settlement_lag_sessions=runtime.settlement_lag_sessions,
        minimum_commission=runtime.minimum_commission,
        commission_rounding=runtime.commission_rounding,
        tax_rounding=runtime.tax_rounding,
        symbol_indices=symbol_indices,
    )
    if runtime.mode in TW_CARRYING_EXECUTION_MODES:
        effective_short_capacity = short_capacity_shares
        if not runtime.short_capacity_limit_enabled:
            shape_source = next(
                (
                    value
                    for value in (
                        short_capacity_shares,
                        short_margin_rate,
                        unresolved_corporate_action_mask,
                    )
                    if value is not None and np.asarray(value).ndim == 2
                ),
                None,
            )
            if shape_source is None:
                raise ValueError(
                    "disabled margin-short capacity limiting requires a "
                    "two-dimensional execution reference"
                )
            # The exact oracle keeps its public fail-closed API: None never
            # means unlimited.  Use an explicit, int64-safe ceiling far above
            # any gross-budget-constrained order instead.
            effective_short_capacity = np.full(
                np.asarray(shape_source).shape,
                8_000_000_000_000_000_000,
                dtype=np.int64,
            )
        kwargs.update(
            can_short_open_open_mask=can_short_open_open_mask,
            short_lot_sizes=(
                None
                if runtime.short_lot_sizes is None
                else np.asarray(runtime.short_lot_sizes, dtype=np.int64)
            ),
            short_margin_rate=(
                runtime.short_initial_margin_rate
                if short_margin_rate is None
                else np.maximum(
                    np.nan_to_num(
                        np.asarray(short_margin_rate, dtype=np.float64),
                        nan=runtime.short_initial_margin_rate,
                        posinf=runtime.short_initial_margin_rate,
                        neginf=runtime.short_initial_margin_rate,
                    ),
                    runtime.short_initial_margin_rate,
                )
            ),
            short_capacity_shares=effective_short_capacity,
            short_maintenance_ratio=runtime.short_maintenance_ratio,
            short_handling_fee_rate=runtime.short_handling_fee_rate,
        )
    return kwargs


def _integer_audit_initial_capital(
    config: ExperimentConfig,
    runtime: _ExecutionRuntime,
) -> float:
    """Use the same absolute-equity anchor as the volume-cap surrogate."""

    if runtime.mode in CONTINUOUS_WEIGHT_EXECUTION_MODES:
        return 1_000_000.0
    if runtime.mode in {"tw_index_futures_day", "tw_index_derivatives_day"}:
        return float(runtime.futures_initial_capital)
    capital = float(config.trading.volume_participation_equity)
    if not math.isfinite(capital) or capital <= 0.0:
        raise ValueError(
            "Taiwan exact execution requires trading.volume_participation_equity "
            "to be finite and positive"
        )
    return capital


def _integer_audit_requested_weights(
    result: BacktestResult,
    runtime: _ExecutionRuntime,
) -> np.ndarray:
    """Return the model request that the integer oracle must execute exactly once."""

    if runtime.mode == "naive":
        return result.weights_history
    requested = result.requested_weights_history
    if requested is None:
        raise RuntimeError(
            f"{runtime.mode} integer audit requires original requested_weights_history; "
            "replaying realised continuous weights would apply portfolio and execution "
            "constraints a second time"
        )
    requested_array = np.asarray(requested)
    realised_shape = tuple(np.asarray(result.weights_history).shape)
    if runtime.mode in {"tw_index_futures_day", "tw_index_derivatives_day"}:
        if requested_array.ndim != 2 or int(requested_array.shape[0]) != int(
            realised_shape[0]
        ):
            raise RuntimeError(
                f"{runtime.mode} integer audit requires direct actions, got "
                f"{requested_array.shape}"
            )
        expected_width = (
            TAIFEX_INDEX_FUTURES_ACTION_COUNT
            if runtime.mode == "tw_index_futures_day"
            else TAIFEX_INDEX_DERIVATIVE_ACTION_COUNT_V4
        )
        if int(requested_array.shape[1]) != expected_width:
            raise RuntimeError(
                f"{runtime.mode} direct action width must be {expected_width}"
            )
        return requested_array
    if (
        requested_array.ndim not in {2, 3}
        or int(requested_array.shape[0]) != int(realised_shape[0])
        or int(requested_array.shape[-1]) != int(realised_shape[1])
    ):
        raise RuntimeError(
            "requested and realised weight histories must share row and symbol "
            f"dimensions for integer audit: {requested_array.shape} vs {realised_shape}"
        )
    expected_phases = (
        2
        if runtime.mode == "tw_cash"
        else 3
        if runtime.mode == "tw_overnight"
        else 1
    )
    if requested_array.ndim == 3 and int(requested_array.shape[1]) != expected_phases:
        raise RuntimeError(
            f"{runtime.mode} integer audit expected {expected_phases} action phases, "
            f"got {requested_array.shape}"
        )
    if runtime.mode == "tw_overnight" and requested_array.ndim != 3:
        raise RuntimeError(
            "tw_overnight integer audit requires [T,3,S] model actions"
        )
    return requested_array


def _canonical_tensor_day_trade_enabled(
    config: ExperimentConfig,
    runtime: _ExecutionRuntime,
) -> bool:
    """Whether the tensor day-trade forward is the experiment's primary result."""

    return bool(
        runtime.mode == "tw_day_trade"
        and (
            config.data.day_trade_minute_execution_root is not None
            or runtime.day_trade_unlimited_margin_conversion
        )
    )


def _tensor_day_trade_is_whole_lot_exact(
    config: ExperimentConfig,
    runtime: _ExecutionRuntime,
) -> bool:
    """Whether a tensor result may stand in for the separate integer audit.

    The minute event executor rounds its forward to exact board lots.  The
    futures portfolio and crypto perpetual modes explicitly have no separate
    integer-execution research layer, so their canonical continuous-notional
    results are also the only reportable results.  The daily cash executor
    deliberately permits fractional weights but does have a distinct integer
    oracle and therefore cannot be reused under an integer label.
    """

    return bool(
        runtime.mode in {"tw_futures_portfolio_day", "crypto_perpetual"}
        or (
            runtime.mode == "tw_day_trade"
            and config.data.day_trade_minute_execution_root is not None
        )
    )


def _run_integer_share_audit_if_supported(
    runtime: _ExecutionRuntime,
    **kwargs: Any,
) -> tuple[BacktestResult | None, list[HoldingsRecord]]:
    """Run the exact oracle only when it implements the declared state ABI.

    The legacy TW day-trade integer oracle closes every position within the
    session.  It therefore cannot audit the unlimited-margin research contract,
    whose residual long/short inventory, financing debt, and segregated short
    collateral are recurrent state.  Returning no audit is safer than
    publishing an internally inconsistent result under an ``integer`` label.
    """

    if (
        runtime.mode == "tw_day_trade"
        and runtime.day_trade_unlimited_margin_conversion
    ):
        return None, []
    result, holdings = run_backtest_integer_shares(**kwargs)
    return result, holdings


def _active_panel_execution_rows(
    panel: PanelData,
    date_indices: np.ndarray,
    symbol_indices: np.ndarray | None = None,
    *,
    execution_mode: str = "naive",
    corporate_action_mode: str = "avoid",
) -> tuple[
    np.ndarray,
    np.ndarray | None,
    np.ndarray | None,
    np.ndarray | None,
    np.ndarray | None,
    np.ndarray | None,
    np.ndarray | None,
    np.ndarray | None,
    np.ndarray | None,
    np.ndarray | None,
    list[str],
]:
    """Slice exact price/rule inputs in the same active symbol order as weights."""

    rows = np.asarray(date_indices, dtype=np.int64)
    local_symbols = None if symbol_indices is None else np.asarray(symbol_indices, dtype=np.int64)

    def select(values: np.ndarray | None) -> np.ndarray | None:
        if values is None:
            return None
        selected = np.asarray(values)[rows]
        return selected if local_symbols is None else selected[:, local_symbols]

    symbols = (
        list(panel.symbols)
        if local_symbols is None
        else [panel.symbols[int(index)] for index in local_symbols.tolist()]
    )
    close_prices = select(panel.close_prices)
    if close_prices is None:
        raise ValueError("integer execution audit requires close prices")
    execution_volumes = select(panel.daily_volumes)
    if execution_mode != "naive" and panel.daily_volumes is not None:
        # Match the differentiable dataset: neither an open nor a close fill may
        # use the eventual full-session volume, which includes information from
        # the closing auction.  Use only the last completed session's shares.
        prior_rows = rows - 1
        prior = np.zeros(
            (rows.size, len(panel.symbols)),
            dtype=np.asarray(panel.daily_volumes).dtype,
        )
        valid_prior = prior_rows >= 0
        if np.any(valid_prior):
            prior[valid_prior] = np.asarray(panel.daily_volumes)[prior_rows[valid_prior]]
        prior = np.where(np.isfinite(prior) & (prior >= 0.0), prior, 0.0)
        execution_volumes = prior if local_symbols is None else prior[:, local_symbols]
    normalized_action_mode = str(corporate_action_mode).strip().lower()
    if normalized_action_mode not in {"avoid", "exact"}:
        raise ValueError("corporate_action_mode must be 'avoid' or 'exact'")
    if normalized_action_mode == "avoid":
        action_mask = panel.corporate_action_avoidance_mask
        has_exact_events = (
            panel.cash_dividend_yield is not None
            and bool((np.asarray(panel.cash_dividend_yield) > 0.0).any())
        )
        if action_mask is None and not has_exact_events:
            action_mask = panel.unresolved_corporate_action_mask
    else:
        action_mask = panel.unresolved_corporate_action_mask
    exact_cash = normalized_action_mode == "exact"
    return (
        close_prices,
        select(panel.open_prices),
        execution_volumes,
        select(panel.day_trade_eligible_mask),
        select(panel.day_trade_can_buy_open_mask),
        select(panel.day_trade_can_sell_open_mask),
        select(panel.can_short_open_open_mask),
        select(action_mask),
        select(panel.cash_dividend_yield) if exact_cash else None,
        (
            select(panel.cash_dividend_payment_delay_sessions)
            if exact_cash
            else None
        ),
        symbols,
    )


def _active_panel_short_contract_rows(
    panel: PanelData,
    date_indices: np.ndarray,
    symbol_indices: np.ndarray | None = None,
    *,
    execution_mode: str,
) -> tuple[np.ndarray | None, np.ndarray | None]:
    """Slice exact point-in-time margin-short inputs for the integer oracle.

    Missing capacity evidence is deliberately represented as zero shares, not
    ``None``: the integer executor interprets ``None`` as no capacity ceiling,
    which is unsafe for a production Taiwan margin-short replay.  Per-symbol
    margin rates are floored by the official market-wide schedule on each
    active exchange date; a receipt-backed higher rate remains binding.
    """

    if normalize_execution_mode(execution_mode) not in TW_CARRYING_EXECUTION_MODES:
        return None, None

    rows = np.asarray(date_indices, dtype=np.int64)
    if rows.ndim != 1:
        raise ValueError("date_indices must be a one-dimensional integer array")
    if bool(((rows < 0) | (rows >= panel.num_dates)).any()):
        raise IndexError("date_indices contains a row outside PanelData")
    local_symbols = (
        None
        if symbol_indices is None
        else np.asarray(symbol_indices, dtype=np.int64)
    )
    if local_symbols is not None:
        if local_symbols.ndim != 1:
            raise ValueError("symbol_indices must be a one-dimensional integer array")
        if bool(
            ((local_symbols < 0) | (local_symbols >= panel.num_symbols)).any()
        ):
            raise IndexError("symbol_indices contains a column outside PanelData")
    symbol_count = panel.num_symbols if local_symbols is None else local_symbols.size
    expected_shape = (panel.num_dates, panel.num_symbols)

    raw_capacity = panel.short_capacity_shares
    if raw_capacity is None:
        capacity = np.zeros((rows.size, symbol_count), dtype=np.int64)
    else:
        capacity_values = np.asarray(raw_capacity)
        if capacity_values.shape != expected_shape:
            raise ValueError(
                "PanelData.short_capacity_shares must match the panel [T,S] shape"
            )
        selected_capacity = capacity_values[rows]
        if local_symbols is not None:
            selected_capacity = selected_capacity[:, local_symbols]
        if selected_capacity.dtype.kind in {"i", "u"}:
            if (
                selected_capacity.dtype.kind == "i"
                and bool((selected_capacity < 0).any())
            ) or (
                selected_capacity.dtype.kind == "u"
                and selected_capacity.size > 0
                and int(selected_capacity.max()) > np.iinfo(np.int64).max
            ):
                raise ValueError(
                    "short_capacity_shares must contain non-negative int64 shares"
                )
            capacity = selected_capacity.astype(np.int64, copy=False)
        else:
            try:
                selected_float = np.asarray(selected_capacity, dtype=np.float64)
            except (TypeError, ValueError) as exc:
                raise ValueError("short_capacity_shares must be numeric") from exc
            finite = np.isfinite(selected_float)
            invalid = np.isinf(selected_float) | (
                finite
                & (
                    (selected_float < 0.0)
                    | (selected_float != np.floor(selected_float))
                    | (selected_float >= float(2**63))
                )
            )
            if bool(invalid.any()):
                raise ValueError(
                    "short_capacity_shares must contain non-negative integer "
                    "shares or NaN for missing evidence"
                )
            capacity = np.zeros(selected_float.shape, dtype=np.int64)
            capacity[finite] = selected_float[finite].astype(np.int64, copy=False)

    official_floor = official_tw_short_initial_margin_rates(panel.dates[rows])
    official_floor = np.asarray(official_floor, dtype=np.float64).reshape(-1, 1)
    if official_floor.shape != (rows.size, 1):
        raise RuntimeError("official short-margin schedule did not align to dates")
    raw_margin = panel.short_margin_rate
    if raw_margin is None:
        margin_rate = np.broadcast_to(
            official_floor, (rows.size, symbol_count)
        ).copy()
    else:
        try:
            margin_values = np.asarray(raw_margin, dtype=np.float64)
        except (TypeError, ValueError) as exc:
            raise ValueError("PanelData.short_margin_rate must be numeric") from exc
        if margin_values.shape != expected_shape:
            raise ValueError(
                "PanelData.short_margin_rate must match the panel [T,S] shape"
            )
        selected_margin = margin_values[rows]
        if local_symbols is not None:
            selected_margin = selected_margin[:, local_symbols]
        if bool(
            (
                np.isinf(selected_margin)
                | (np.isfinite(selected_margin) & (selected_margin < 0.0))
            ).any()
        ):
            raise ValueError("short_margin_rate must be non-negative or NaN")
        margin_rate = np.maximum(
            np.where(np.isnan(selected_margin), official_floor, selected_margin),
            official_floor,
        )

    return (
        np.ascontiguousarray(capacity, dtype=np.int64),
        np.ascontiguousarray(margin_rate, dtype=np.float64),
    )


@dataclass(slots=True)
class TimingBreakdown:
    total_s: float = 0.0
    fetch_s: float = 0.0
    transfer_s: float = 0.0
    batch_prepare_s: float = 0.0
    prepare_index_build_s: float = 0.0
    prepare_window_slice_s: float = 0.0
    prepare_feature_gather_s: float = 0.0
    prepare_target_gather_s: float = 0.0
    prepare_mask_build_s: float = 0.0
    prepare_nan_fill_s: float = 0.0
    prepare_dtype_cast_s: float = 0.0
    prepare_contiguous_s: float = 0.0
    prepare_clone_s: float = 0.0
    prepare_device_move_s: float = 0.0
    prepare_panel_slab_batch_s: float = 0.0
    prepare_metadata_batch_s: float = 0.0
    prepare_materialized_batch_s: float = 0.0
    prepare_move_windowed_batch_s: float = 0.0
    window_materialize_s: float = 0.0
    h2d_transfer_s: float = 0.0
    forward_s: float = 0.0
    model_forward_s: float = 0.0
    model_forward_cuda_s: float = 0.0
    factor_aug_s: float = 0.0
    factor_aug_cuda_s: float = 0.0
    loss_s: float = 0.0
    loss_cuda_s: float = 0.0
    portfolio_state_s: float = 0.0
    backward_s: float = 0.0
    grad_s: float = 0.0
    grad_cuda_s: float = 0.0
    gradient_norm_before_clip_sum: float = 0.0
    gradient_norm_zero_batches: int = 0
    gradient_norm_observations: int = 0
    gradient_norm_first_zero_batch: int = -1
    portfolio_first_dead_batch: int = -1
    portfolio_first_default_row: int = -1
    portfolio_first_default_reason: int = 0
    portfolio_final_alive: int = 1
    clip_s: float = 0.0
    clip_cuda_s: float = 0.0
    finite_check_s: float = 0.0
    step_s: float = 0.0
    step_cuda_s: float = 0.0
    scheduler_s: float = 0.0
    backtest_s: float = 0.0
    backtest_prepare_s: float = 0.0
    backtest_runner_s: float = 0.0
    backtest_finalize_s: float = 0.0
    ic_s: float = 0.0
    metrics_s: float = 0.0
    concat_s: float = 0.0
    save_s: float = 0.0
    plot_s: float = 0.0
    sync_s: float = 0.0
    cpu_gpu_sync_s: float = 0.0
    iter_start_sync_s: float = 0.0
    after_prepare_sync_s: float = 0.0
    after_forward_sync_s: float = 0.0
    after_loss_sync_s: float = 0.0
    after_backward_sync_s: float = 0.0
    after_step_sync_s: float = 0.0
    gc_s: float = 0.0
    batches: int = 0
    cuda_events: list[tuple[str, torch.device, torch.cuda.Event, torch.cuda.Event]] = field(
        default_factory=list
    )


def _broadcast_epoch_eval_tensor(
    value: torch.Tensor | None,
    *,
    count: int,
    src: int,
    device: torch.device,
) -> torch.Tensor | None:
    """Broadcast a small rank-owned eval result without copying market tensors."""
    count = max(0, int(count))
    if count == 0:
        return None
    if not _distributed_is_initialized() or _distributed_world_size() <= 1:
        if value is None or int(value.numel()) != count:
            raise RuntimeError(f"epoch eval expected {count} scalar(s)")
        return value
    if _distributed_rank() == int(src):
        if value is None or int(value.numel()) != count:
            raise RuntimeError(
                f"epoch eval source rank {src} expected {count} scalar(s)"
            )
        payload = value.detach().to(device=device, dtype=torch.float32).reshape(count).contiguous()
    else:
        payload = torch.empty((count,), device=device, dtype=torch.float32)
    dist.broadcast(payload, src=int(src))
    return payload


def _broadcast_epoch_eval_timing(
    timing: TimingBreakdown,
    *,
    elapsed_s: float,
    loss_s: float,
    src: int,
    device: torch.device,
) -> tuple[TimingBreakdown, float, float]:
    """Move timing metadata from an eval worker rank to the reporting rank."""
    if not _distributed_is_initialized() or _distributed_world_size() <= 1:
        return timing, float(elapsed_s), float(loss_s)
    names = [name for name in TimingBreakdown.__dataclass_fields__ if name != "cuda_events"]
    if _distributed_rank() == int(src):
        values = [float(getattr(timing, name)) for name in names]
        values.extend((float(elapsed_s), float(loss_s)))
        payload = torch.tensor(values, device=device, dtype=torch.float64)
    else:
        payload = torch.empty((len(names) + 2,), device=device, dtype=torch.float64)
    dist.broadcast(payload, src=int(src))
    values = payload.detach().cpu().tolist()
    resolved = TimingBreakdown()
    for name, raw in zip(names, values[:-2], strict=True):
        setattr(
            resolved,
            name,
            int(raw)
            if name
            in {
                "batches",
                "gradient_norm_zero_batches",
                "gradient_norm_observations",
                "gradient_norm_first_zero_batch",
                "portfolio_first_dead_batch",
                "portfolio_first_default_row",
                "portfolio_first_default_reason",
                "portfolio_final_alive",
            }
            else float(raw),
        )
    return resolved, float(values[-2]), float(values[-1])


def _log_timing(label: str, timing: TimingBreakdown) -> None:
    parts = [f"[profile] {label}: total={timing.total_s:.3f}s"]
    if timing.batches:
        parts.append(f"batches={timing.batches}")
    for name in (
        "fetch_s",
        "transfer_s",
        "batch_prepare_s",
        "prepare_index_build_s",
        "prepare_window_slice_s",
        "prepare_feature_gather_s",
        "prepare_target_gather_s",
        "prepare_mask_build_s",
        "prepare_nan_fill_s",
        "prepare_dtype_cast_s",
        "prepare_contiguous_s",
        "prepare_clone_s",
        "prepare_device_move_s",
        "prepare_panel_slab_batch_s",
        "prepare_metadata_batch_s",
        "prepare_materialized_batch_s",
        "prepare_move_windowed_batch_s",
        "window_materialize_s",
        "h2d_transfer_s",
        "forward_s",
        "model_forward_s",
        "model_forward_cuda_s",
        "factor_aug_s",
        "factor_aug_cuda_s",
        "loss_s",
        "loss_cuda_s",
        "portfolio_state_s",
        "backward_s",
        "grad_s",
        "grad_cuda_s",
        "clip_s",
        "clip_cuda_s",
        "finite_check_s",
        "step_s",
        "step_cuda_s",
        "scheduler_s",
        "backtest_s",
        "backtest_prepare_s",
        "backtest_runner_s",
        "backtest_finalize_s",
        "ic_s",
        "metrics_s",
        "concat_s",
        "save_s",
        "plot_s",
        "sync_s",
        "cpu_gpu_sync_s",
        "iter_start_sync_s",
        "after_prepare_sync_s",
        "after_forward_sync_s",
        "after_loss_sync_s",
        "after_backward_sync_s",
        "after_step_sync_s",
        "gc_s",
    ):
        value = getattr(timing, name)
        if value > 0:
            parts.append(f"{name[:-2]}={value:.3f}s")
    if timing.gradient_norm_observations > 0:
        parts.append(
            "grad_norm_before_clip="
            f"{timing.gradient_norm_before_clip_sum / timing.gradient_norm_observations:.6g}"
        )
        parts.append(
            "zero_grad_batches="
            f"{timing.gradient_norm_zero_batches}/{timing.gradient_norm_observations}"
        )
    print(" ".join(parts))


